// Ported from Slashy origin/main:mobile/ios-messages-extension/SlashyTokens.swift
// (itself generated by mobile/scripts/generate-slashy-tokens.js from
// mobile/lib/colors.ts, components/nav/navMetrics.ts,
// components/nav/navMaterial.ts and global.css).
//
// Values are copied verbatim. Only the names changed: the namespace is
// `Tokens`, and the nested UIKit palettes are `Palette` / `LightColor` /
// `DarkColor` (Slashy's `Color` / `Text` would shadow SwiftUI's types inside
// `Tokens`). The SwiftUI-facing statics at the bottom of this file are what
// feature code should use.

import SwiftUI
import UIKit

enum Tokens {
    // MARK: - Scale

    /// Control scale by device width. The iPhone 17 Pro (402pt wide) is the
    /// baseline at 1.0, so its controls are Slashy's literal sizes (40, 36,
    /// 48). Wider phones scale up in proportion: the 17 Pro Max (440pt) lands
    /// at about 1.09. Capped so nothing inflates past 1.15. Text size does not
    /// change control sizes.
    /// Read once, on first use from a view body (always the main thread).
    static let uiScale: CGFloat = {
        let width: CGFloat = MainActor.assumeIsolated {
            let bounds = UIApplication.shared.connectedScenes
                .compactMap { ($0 as? UIWindowScene)?.screen.bounds }
                .first
            return bounds.map { min($0.width, $0.height) } ?? 402
        }
        return min(max(width / 402, 1), 1.15)
    }()

    /// A baseline length on this device, snapped to whole pixels (thirds of a
    /// point on a 3x screen) so edges stay crisp while proportions stay exact.
    static func scaled(_ points: CGFloat) -> CGFloat {
        (points * uiScale * 3).rounded() / 3
    }

    private static func dynamic(light: UIColor, dark: UIColor) -> UIColor {
        UIColor { $0.userInterfaceStyle == .dark ? dark : light }
    }

