    //
    // `radius` is the CSS blur halved: a Core Graphics shadow radius is
    // roughly half the equivalent CSS blur.

    struct Shadow: Sendable {
        let x: CGFloat
        let y: CGFloat
        let radius: CGFloat
        let color: UIColor
        var opacity: Double { color.cgColor.alpha }
    }

