    static let foregroundSecondary = Color(uiColor: Palette.foregroundSecondary)
    static let foregroundMuted = Color(uiColor: Palette.foregroundMuted)
    static let foregroundInverse = Color(uiColor: Palette.foregroundInverse)
    static let background = Color(uiColor: Palette.background)
    static let drawerBackground = Color(uiColor: Palette.drawerBackground)
    static let surface = Color(uiColor: Palette.surface)
    static let hover = Color(uiColor: Palette.hover)
    static let border = Color(uiColor: Palette.border)
    static let accent = Color(uiColor: Palette.accent)
    static let composeSurface = Color(uiColor: Palette.composeSurface)
    static let destructive = Color(uiColor: Palette.destructive)
    static let filePDF = Color(uiColor: Palette.filePDF)
    static let fileDocument = Color(uiColor: Palette.fileDocument)
    static let fileSpreadsheet = Color(uiColor: Palette.fileSpreadsheet)

    /// The ask bubble (`Material.askBubble`): #E6E6E6 light / #26262A dark.
    static let userBubble = Color(uiColor: Material.askBubble)

    /// RECORD_RED, #E12432 in both schemes.
    static let recording = Color(uiColor: UIColor(red: 0.882353, green: 0.141176, blue: 0.196078, alpha: 1))

    /// Sheet cards: black 5% light / white 7% dark.
    static let cardFill = Color(uiColor: dynamicColor(
        light: UIColor(red: 0, green: 0, blue: 0, alpha: 0.05),
        dark: UIColor(red: 1, green: 1, blue: 1, alpha: 0.07)
    ))

    /// Sheet row press wash: black 5% light / white 6% dark.
    static let pressWash = Color(uiColor: dynamicColor(
        light: UIColor(red: 0, green: 0, blue: 0, alpha: 0.05),
        dark: UIColor(red: 1, green: 1, blue: 1, alpha: 0.06)
    ))

    /// The glass rim and sheet row dividers (`Material.edge`):
    /// rgba(0,0,0,0.10) light / rgba(255,255,255,0.09) dark.
    static let hairline = Color(uiColor: Material.edge)

    private static func dynamicColor(light: UIColor, dark: UIColor) -> UIColor {
        UIColor { $0.userInterfaceStyle == .dark ? dark : light }
    }
}

// MARK: - Type sizes (global.css @theme)

extension Tokens {
    static let footnote: CGFloat = 13
    static let subhead: CGFloat = 15
    static let callout: CGFloat = 16
    static let body: CGFloat = 17
    static let title3: CGFloat = 20
    /// Used semibold.
    static let title: CGFloat = 24
}

// MARK: - Motion

extension Tokens {
    enum Motion {
        /// The push-reveal drawer: 250ms easeInOut.
        static let drawer: Animation = .easeInOut(duration: 0.25)
        /// Composer primary-button swaps.
        static let buttonSwap: Animation = .interpolatingSpring(mass: 0.85, stiffness: 160, damping: 22)
        /// Voice controls sliding in from the right.
        static let voiceIn: Animation = .interpolatingSpring(mass: 0.85, stiffness: 170, damping: 19)
        /// The 140ms glyph crossfade.
        static let crossfade: Animation = .easeInOut(duration: 0.14)
    }
}
